var click;
// === Tab: Bead ===
class Bead {
	constructor(pos, dim, maxZ, minZ, state, type, val, place, pow) {
		this.pos = pos;
		this.dim = dim;
		this.tpos = createVector(pos.x, pos.y, pos.z);
		if (type == 'top') this.positions = [maxZ, minZ];
		else this.positions = [minZ, maxZ];
		this.state = state;
		this.f = 'black';
		this.type = type;
		this.val = val;
		this.place = place;
		this.pow = pow;
	}
	move(){
		this.tpos.z = this.positions[this.state];
		this.pos.lerp(this.tpos, 0.2);
	}
	show() {
		push();
		translate(this.pos);
		fill(this.f);
		rotateX(HALF_PI);
		shininess(3)
		ellipsoid(this.dim.x, this.dim.y, this.dim.z)
		pop();
	}
	contains(x, z) {
		return ((x > this.pos.x - this.dim.x) && (x < this.pos.x + this.dim.x) && (z > this.pos.z - this.dim.y) && (z < this.pos.z + this.dim.y));
	}
}

