// For the #WCCChallenge, theme: "upside down." 
// On this device, every upside bead moved down is +5 times the place value of the bead.
// Every downside bead moved up is +1 times the place value of the bead.

var wood;
var beads = [];
var rods = [];
var zoom;
var cnv;
var lm;
var rotX = 0;
var rotY = 0;

function preload() {
	wood = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/teak.jpeg');
	click = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/click1.wav');
}

function setup() {
	cnv = createCanvas(windowWidth, windowHeight, WEBGL);
	zoom = height / 450;
	cnv.mousePressed(beadClick);
	lm = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	makeBeads();
	makeHTML();
}

function makeBeads() {
	// Top beads
	for (i = 0; i < 9; i++) {
		var x = map(i, 0, 8, -200, 200);
		for (j = 0; j < 2; j++) {
			let z = (-30 - 16 - 20) + (j * 20)
			let pos = createVector(x, 0, z);
			let dim = createVector(20, 10, 20);
			let maxZ = (-150 + 16) + (j * 20);
			let minZ = z;
			pos.z = maxZ;
			let bead = new Bead(pos, dim, maxZ, minZ, 0, 'top', j, 8 - i, 5);
			beads.push(bead);
		}
	}
	// Bottom beads
	for (i = 0; i < 9; i++) {
		var x = map(i, 0, 8, -200, 200);
		for (k = 0; k < 5; k++) {
			var z = (160 - 16 - 10) - (k * 20);
			var pos = createVector(x, 0, z);
			var dim = createVector(20, 10, 20);
			var maxZ = (-30 + 16 + 4 * 20 - k * 20);
			var minZ = z;
			var bead = new Bead(pos, dim, maxZ, minZ, 0, 'bottom', k, 8 - i, 1);
			beads.push(bead);
		}
	}
}

function draw() {
	scale(zoom);
	background(0);
	ambientLight(160);
	lm.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0.1);
	pointLight(120, 120, 120, map(lm.x, 0, width, -height, height), map(lm.y, 0, height, -height, height), height);
	specularMaterial(200);
	if (infobox.checked()) {
		rotX = lerp(rotX, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, HALF_PI, -HALF_PI), 0.1);
		rotY = lerp(rotY, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -HALF_PI, HALF_PI), 0.1);
	} else {
		rotX = lerp(rotX, 0, 0.2);
		rotY = lerp(rotY, 0, 0.2);
	}
	rotateY(rotY);
	rotateX(rotX - HALF_PI);
	drawFrame();
	for (b of beads) {
		if(frameCount>b.val) b.move();
		b.show();
	}
}

function drawFrame() {
	texture(wood);
	noStroke();
	push();
	translate(-250, 0, 0);
	box(16, 32, 316);
	pop();
	push();
	translate(250, 0, 0);
	box(16, 32, 316);
	pop();
	push();
	translate(0, 0, 150);
	box(500 - 16, 32, 16);
	pop();
	push();
	translate(0, 0, -150);
	box(500 - 16, 32, 16);
	pop();
	push();
	translate(0, 0, -30);
	box(500 - 16, 32, 12);
	pop();
	for (i = 0; i < 9; i += 1) {
		var x = map(i, 0, 8, -200, 200);
		push();
		translate(x, 0, 0);
		rotateX(HALF_PI);
		fill('peru');
		cylinder(4, 318)
		pop();
	}
}

function keyPressed() {
	let count = 0;
	if (keyCode == 32) {
		for (b of beads) {
			if (b.state == 1) {
				b.state = 0;
				count += 1;
			}
		}
	}
	if ((keyCode == UP_ARROW || keyCode == RIGHT_ARROW) && slider.value() < 999999999 && slider.elt != document.activeElement) {
		slider.value(slider.value() + 1);
		updateBeads();
	}
	if ((keyCode == DOWN_ARROW || keyCode == LEFT_ARROW) && slider.value() > 0 && slider.elt != document.activeElement) {
		slider.value(slider.value() - 1);
		updateBeads();
	}
	if (count > 0) setTimeout(playClick, 90);
	let newnum = calculateValue()
	display.html(newnum);
	slider.value(newnum);

}

function updateDisplay() {
	display.html(nf(slider.value(), 9));
}

function beadClick() {
	frameCount=0
	for (i = 0; i < beads.length; i++) {
		let b = beads[i];
		if (b.contains(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / zoom, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / zoom)) {
			setTimeout(playClick, 120);
			click.pan(map(b.pos.x, -height / 2, height / 2, -1, 1))
			b.state = 1 - b.state;
			switch (b.type) {
				case 'top':
					if (b.state == 1) {
						if (i % 2 == 0) beads[i + 1].state = b.state;
					} else {
						if (i % 2 == 1) beads[i - 1].state = b.state;
					}
					break;
				case 'bottom':
					if (b.state == 1) {
						for (j = 1; j < 5 - b.val; j++) {
							beads[i + j].state = b.state;
						}
						break;
					} else {
						for (j = 1; j < b.val + 1; j++) {
							beads[i - j].state = b.state;
						}
						break;
					}
					break;
			}
		}
	}
	var newnum = calculateValue();
	display.html(newnum);
	slider.value(newnum);
}

function playClick() {
	click.play();
}

function calculateValue() {
	let num = 0;
	let add = 0;
	for (b of beads) {
		num += b.pow * b.state * Math.pow(10, b.place);
	}
	return nf(num, 9);
}

function updateBeads() {
	let newval = slider.value();
	let digits = [];
	for (i = 0; i < 10; i++) {
		let d = floor(newval / Math.pow(10, i)) % 10;
		digits.push(d);
	}
	for (i = 0; i < digits.length; i++) {
		for (b of beads) {
			if (b.place == i) {
				if (digits[i] != 0) {
					b.state = 0;
					if (digits[i] > 4 && b.val == 1 && b.type == 'top') b.state = 1;
					if (digits[i] % 5 > 4 - b.val && b.type == 'bottom') b.state = 1;
				} else {
					b.state = 0;
				}
			}
		}
	}
	display.html(nf(newval, 9));
	setTimeout(playClick, 100);
}

